 71	  '/reports': { title: 'Reports', snapshot: 'reports', render: renderReports },
 72	  '/secrets': { title: 'Secrets', snapshot: 'secrets', render: renderSecrets },
 73	  '/webhooks': { title: 'Webhooks', snapshot: 'webhooks', render: renderWebhooks },
 74	};
