     1	import { esc } from '#kit/utils';
     2	
     3	/**
     4	 * Page title row.
     5	 *
     6	 * @param {{title: string, subtitle?: string, actions?: string}} opts
     7	 *   `actions` is trusted HTML.
     8	 * @returns {string}
     9	 */
    10	export function pageHeader({ title, subtitle = '', actions = '' }) {
    11	  const sub = subtitle ? `<p class="kit-muted">${esc(subtitle)}</p>` : '';
    12	  const act = actions ? `<div class="kit-page-header__actions">${actions}</div>` : '';
    13	  return `<header class="kit-page-header"><div><h1>${esc(title)}</h1>${sub}</div>${act}</header>`;
