/* Keel admin template */
:root { --kit-ok: #1a7f37; --kit-warn: #9a6700; --kit-bad: #cf222e; --kit-info: #0969da; --kit-muted: #57606a; --kit-border: #d0d7de; }
.kit-muted { color: var(--kit-muted); margin: 0; }
